#include <Arduino.h>
#include <Servo.h>
Servo servo1;
const int BUTTON1_PIN = 2;  
const int BUTTON2_PIN = 3;  
const int BUTTON3_PIN = 4;  
const int BARGRAPH1_PINS[] = {5, 6, 7, 8, 9, 10, 11, 12, 13, 44};  

void setup();
void loop();
void updateBarGraph(int numLEDs);
void setup() {
  servo1.attach(45);  
  pinMode(BUTTON1_PIN, INPUT_PULLUP);
  pinMode(BUTTON2_PIN, INPUT_PULLUP);
  pinMode(BUTTON3_PIN, INPUT_PULLUP);
  for (int i = 0; i < 10; i++) {
    pinMode(BARGRAPH1_PINS[i], OUTPUT);
    digitalWrite(BARGRAPH1_PINS[i], LOW);
  }
  servo1.write(0);
}
void loop() {
  if (digitalRead(BUTTON1_PIN) == LOW) {
    delay(100);
    if (digitalRead(BUTTON1_PIN) == HIGH) {
      servo1.write(30);
      updateBarGraph(3);
    }
  }
  if (digitalRead(BUTTON2_PIN) == LOW) {
    delay(100);
    if (digitalRead(BUTTON2_PIN) == HIGH) {
      servo1.write(60);
      updateBarGraph(6);
    }
  }
  if (digitalRead(BUTTON3_PIN) == LOW) {
    delay(100);
    if (digitalRead(BUTTON3_PIN) == HIGH) {
      servo1.write(90);
      updateBarGraph(10);
    }
  }
}
void updateBarGraph(int numLEDs) {
  for (int i = 0; i < 10; i++) {
    digitalWrite(BARGRAPH1_PINS[i], i < numLEDs ? HIGH : LOW);
  }
}
